  buzzer_set(false);

  /* Close GPIO */

  if (g_safety.buzzer_fd >= 0)
    {
      close(g_safety.buzzer_fd);
      g_safety.buzzer_fd = -1;
    }

  pthread_mutex_destroy(&g_safety.lock);
}

void safety_register_callback(safety_callback_t callback, FAR void *arg)
{
