/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <debug.h>
#include <errno.h>
#include <syslog.h>

#include <nuttx/net/bluetooth.h>
#include <nuttx/wireless/bluetooth/bt_driver.h>
#include <nuttx/wireless/bluetooth/bt_gatt.h>

#include "smart_lock_config.h"
#include "ble_service.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG "ble_svc"
#define BLE_DEVICE_NAME "SmartLock"
#define BLE_MTU 20

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct ble_ctx_s
{
  volatile bool initialized;
  volatile bool advertising;
  struct ble_status_s status;
  ble_event_callback_t callback;
  FAR void *callback_arg;
  pthread_mutex_t lock;

  /* GATT handles */

  uint16_t service_handle;
  uint16_t door_state_handle;
  uint16_t door_ctrl_handle;
  uint16_t config_handle;
  uint16_t notify_handle;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct ble_ctx_s g_ble;

/* GATT Service Definition */

static const struct bt_gatt_attr g_smart_lock_attrs[] =
{
  /* Service Declaration */

  BT_GATT_PRIMARY_SERVICE(BT_UUID_DECLARE_16(SMART_LOCK_SERVICE_UUID)),

  /* Door State Characteristic */

  BT_GATT_CHARACTERISTIC(BT_UUID_DECLARE_16(DOOR_STATE_CHAR_UUID),
                         BT_GATT_CHRC_READ | BT_GATT_CHRC_NOTIFY),
  BT_GATT_DESCRIPTOR(BT_UUID_DECLARE_16(BT_GATT_CCC),
                     BT_GATT_PERM_READ | BT_GATT_PERM_WRITE,
                     NULL, NULL, NULL),

  /* Door Control Characteristic */

  BT_GATT_CHARACTERISTIC(BT_UUID_DECLARE_16(DOOR_CONTROL_CHAR_UUID),
                         BT_GATT_CHRC_WRITE),
  BT_GATT_DESCRIPTOR(BT_UUID_DECLARE_16(BT_GATT_CCC),
                     BT_GATT_PERM_WRITE,
                     NULL, NULL, NULL),

  /* Configuration Characteristic */

  BT_GATT_CHARACTERISTIC(BT_UUID_DECLARE_16(CONFIG_CHAR_UUID),
                         BT_GATT_CHRC_READ | BT_GATT_CHRC_WRITE),
  BT_GATT_DESCRIPTOR(BT_UUID_DECLARE_16(BT_GATT_CCC),
                     BT_GATT_PERM_READ | BT_GATT_PERM_WRITE,
                     NULL, NULL, NULL),

  /* Notification Characteristic */

  BT_GATT_CHARACTERISTIC(BT_UUID_DECLARE_16(NOTIFICATION_CHAR_UUID),
                         BT_GATT_CHRC_NOTIFY),
  BT_GATT_DESCRIPTOR(BT_UUID_DECLARE_16(BT_GATT_CCC),
                     BT_GATT_PERM_READ | BT_GATT_PERM_WRITE,
                     NULL, NULL, NULL),
};

static struct bt_gatt_service g_smart_lock_svc =
{
  .attrs = g_smart_lock_attrs,
  .attr_count = sizeof(g_smart_lock_attrs) / sizeof(g_smart_lock_attrs[0]),
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ble_door_state_read
 *
 * Description:
 *   Handle read request for door state characteristic.
 *
 ****************************************************************************/

static ssize_t ble_door_state_read(FAR struct bt_conn *conn,
                                   FAR const struct bt_gatt_attr *attr,
                                   FAR void *buf, uint16_t len,
                                   uint16_t offset)
{
  uint8_t state;

  pthread_mutex_lock(&g_ble.lock);
  state = g_ble.status.connected ? BLE_DOOR_STATE_OPEN :
                                   BLE_DOOR_STATE_CLOSED;
  pthread_mutex_unlock(&g_ble.lock);

  return bt_gatt_attr_read(conn, attr, buf, len, offset, &state, 1);
}

/****************************************************************************
 * Name: ble_door_ctrl_write
 *
 * Description:
 *   Handle write request for door control characteristic.
 *
 ****************************************************************************/

static ssize_t ble_door_ctrl_write(FAR struct bt_conn *conn,
                                   FAR const struct bt_gatt_attr *attr,
                                   FAR const void *buf, uint16_t len,
                                   uint16_t offset, uint8_t flags)
{
  FAR const uint8_t *data = buf;
  uint8_t cmd;

  if (len < 1)
    {
      return BT_GATT_ERR(BT_ATT_ERR_INVALID_ATTRIBUTE_LEN);
    }

  cmd = data[0];
  syslog(LOG_INFO, TAG": Control command: 0x%02x\n", cmd);

  /* Notify callback */

  if (g_ble.callback != NULL)
    {
      g_ble.callback(cmd, data + 1, len - 1, g_ble.callback_arg);
    }

  return len;
}

/****************************************************************************
 * Name: ble_connected
 *
 * Description:
 *   Handle BLE connection event.
 *
 ****************************************************************************/

static void ble_connected(FAR struct bt_conn *conn, uint8_t err)
{
  if (err != 0)
    {
      syslog(LOG_WARNING, TAG": Connection failed: %d\n", err);
      return;
    }

  syslog(LOG_INFO, TAG": Connected\n");

  pthread_mutex_lock(&g_ble.lock);
  g_ble.status.connected = true;
  g_ble.status.conn_handle = (uint16_t)(unsigned long)conn;
  bt_conn_get_info(conn, g_ble.status.addr);
  pthread_mutex_unlock(&g_ble.lock);

  /* Notify callback */

  if (g_ble.callback != NULL)
    {
      g_ble.callback(BLE_NOTIFY_STATE_CHANGE, NULL, 0,
                     g_ble.callback_arg);
    }
}

/****************************************************************************
 * Name: ble_disconnected
 *
 * Description:
 *   Handle BLE disconnection event.
 *
 ****************************************************************************/

static void ble_disconnected(FAR struct bt_conn *conn, uint8_t reason)
{
  syslog(LOG_INFO, TAG": Disconnected: reason=%d\n", reason);

  pthread_mutex_lock(&g_ble.lock);
  g_ble.status.connected = false;
  g_ble.status.conn_handle = 0;
  memset(g_ble.status.addr, 0, sizeof(g_ble.status.addr));
  pthread_mutex_unlock(&g_ble.lock);

  /* Restart advertising */

  ble_service_start_advertising();

  /* Notify callback */

  if (g_ble.callback != NULL)
    {
      g_ble.callback(BLE_NOTIFY_STATE_CHANGE, NULL, 0,
                     g_ble.callback_arg);
    }
}

/* Connection callbacks */

static struct bt_conn_cb g_conn_callbacks =
{
  .connected = ble_connected,
  .disconnected = ble_disconnected,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int ble_service_init(void)
{
  int ret;

  syslog(LOG_INFO, TAG": Initializing BLE service\n");

  /* Initialize context */

  memset(&g_ble, 0, sizeof(g_ble));
  g_ble.initialized = false;
  g_ble.advertising = false;
  pthread_mutex_init(&g_ble.lock, NULL);

  /* Set device name */

  ret = bt_set_name(BLE_DEVICE_NAME);
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": Failed to set name: %d\n", ret);
      goto err;
    }

  /* Register GATT service */

  ret = bt_gatt_service_register(&g_smart_lock_svc);
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": Failed to register service: %d\n", ret);
      goto err;
    }

  /* Register connection callbacks */

  bt_conn_cb_register(&g_conn_callbacks);

  /* Enable BLE */

  ret = bt_enable(NULL);
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": Failed to enable BLE: %d\n", ret);
      goto err;
    }

  g_ble.initialized = true;

  /* Start advertising */

  ret = ble_service_start_advertising();
  if (ret < 0)
    {
      syslog(LOG_WARNING, TAG": Failed to start advertising: %d\n", ret);
      /* Non-fatal - can start advertising later */
    }

  syslog(LOG_INFO, TAG": BLE service initialized\n");
  return 0;

err:
  pthread_mutex_destroy(&g_ble.lock);
  return ret;
}

void ble_service_deinit(void)
{
  syslog(LOG_INFO, TAG": Deinitializing BLE service\n");

  ble_service_stop_advertising();

  g_ble.initialized = false;
  pthread_mutex_destroy(&g_ble.lock);
}

void ble_service_register_callback(ble_event_callback_t callback,
                                   FAR void *arg)
{
  pthread_mutex_lock(&g_ble.lock);
  g_ble.callback = callback;
  g_ble.callback_arg = arg;
  pthread_mutex_unlock(&g_ble.lock);
}

int ble_service_update_door_state(uint8_t state)
{
  int ret;

  if (!g_ble.initialized)
    {
      return -ENODEV;
    }

  /* Update characteristic value */

  ret = bt_gatt_notify(NULL, &g_smart_lock_attrs[1], &state, 1);
  if (ret < 0)
    {
      syslog(LOG_WARNING, TAG": Notify failed: %d\n", ret);
    }

  return ret;
}

int ble_service_send_notification(uint8_t type, FAR const uint8_t *data,
                                  size_t len)
{
  uint8_t buf[BLE_MTU + 1];
  size_t send_len;

  if (!g_ble.initialized || !g_ble.status.connected)
    {
      return -ENOTCONN;
    }

  /* Prepare notification data */

  buf[0] = type;
  send_len = (len > BLE_MTU - 1) ? BLE_MTU - 1 : len;
  if (data != NULL && send_len > 0)
    {
      memcpy(buf + 1, data, send_len);
    }

  send_len++;  /* Include type byte */

  /* Send notification */

  return bt_gatt_notify(NULL, &g_smart_lock_attrs[7], buf, send_len);
}

void ble_service_get_status(FAR struct ble_status_s *status)
{
  if (status == NULL)
    {
      return;
    }

  pthread_mutex_lock(&g_ble.lock);
  *status = g_ble.status;
  pthread_mutex_unlock(&g_ble.lock);
}

bool ble_service_is_connected(void)
{
  return g_ble.status.connected;
}

int ble_service_start_advertising(void)
{
  struct bt_le_adv_param param;
  int ret;

  if (!g_ble.initialized)
    {
      return -ENODEV;
    }

  if (g_ble.advertising)
    {
      return 0;  /* Already advertising */
    }

  /* Configure advertising parameters */

  memset(&param, 0, sizeof(param));
  param.options = BT_LE_ADV_OPT_CONNECTABLE | BT_LE_ADV_OPT_SCANNABLE;
  param.interval_min = BT_GAP_ADV_FAST_INT_MIN_2;
  param.interval_max = BT_GAP_ADV_FAST_INT_MAX_2;

  /* Start advertising */

  ret = bt_le_adv_start(&param, NULL, 0, NULL, 0);
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": Failed to start advertising: %d\n", ret);
      return ret;
    }

  g_ble.advertising = true;
  syslog(LOG_INFO, TAG": Advertising started\n");

  return 0;
}

void ble_service_stop_advertising(void)
{
  if (g_ble.advertising)
    {
      bt_le_adv_stop();
      g_ble.advertising = false;
      syslog(LOG_INFO, TAG": Advertising stopped\n");
    }
}

