/****************************************************************************
 * Private Types
 ****************************************************************************/

struct voice_ctx_s
{
  volatile bool initialized;
  volatile bool playing;
  volatile bool enabled;
  uint8_t volume;
  uint8_t current_priority;
  pthread_mutex_t lock;
  pthread_t play_tid;
  int audio_fd;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct voice_ctx_s g_voice;

/* Voice file name mapping */

static const FAR char *g_voice_files[] =
{
  [VOICE_ID_DOOR_OPENING]     = "door_opening",
  [VOICE_ID_DOOR_CLOSING]     = "door_closing",
  [VOICE_ID_DOOR_LOCKED]      = "door_locked",
  [VOICE_ID_ANTI_PINCH_WARN]  = "anti_pinch_warn",
  [VOICE_ID_ABNORMAL_ALARM]   = "abnormal_alarm",
  [VOICE_ID_WELCOME]          = "welcome",
  [VOICE_ID_GOODBYE]          = "goodbye",
  [VOICE_ID_TIMEOUT_WARNING]  = "timeout_warning",
  [VOICE_ID_DOORBELL]         = "doorbell",
};

#define VOICE_FILE_COUNT (sizeof(g_voice_files) / sizeof(g_voice_files[0]))

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: voice_play_task
 *
 * Description:
 *   Background task that plays voice files.
 *
 ****************************************************************************/

static FAR void *voice_play_task(FAR void *arg)
{
  uint8_t voice_id = (uint8_t)(unsigned long)arg;
  char filepath[64];
  int fd;
  uint8_t buffer[AUDIO_BUFFER_SIZE];
  ssize_t nread;
  ssize_t nwritten;

  if (voice_id >= VOICE_FILE_COUNT || g_voice_files[voice_id] == NULL)
    {
      syslog(LOG_ERR, TAG": Invalid voice ID: %d\n", voice_id);
      g_voice.playing = false;
      return NULL;
    }

  /* Build file path */

  snprintf(filepath, sizeof(filepath), "%s%s%s",
           VOICE_FILE_PATH, g_voice_files[voice_id], VOICE_FILE_EXT);

  syslog(LOG_INFO, TAG": Playing: %s\n", filepath);

  /* Open voice file */

  fd = open(filepath, O_RDONLY);
  if (fd < 0)
    {
      syslog(LOG_ERR, TAG": Failed to open %s: %d\n", filepath, errno);
      g_voice.playing = false;
      return NULL;
    }

  /* Play audio data */

  while (g_voice.playing)
    {
      nread = read(fd, buffer, AUDIO_BUFFER_SIZE);
      if (nread <= 0)
        {
          break;  /* End of file or error */
        }

      /* Write to audio device */

      if (g_voice.audio_fd >= 0)
        {
          nwritten = write(g_voice.audio_fd, buffer, nread);
          if (nwritten < 0)
            {
              syslog(LOG_ERR, TAG": Audio write failed: %d\n", errno);
              break;
            }
        }
      else
        {
          /* Simulate playback if no audio device */

          usleep(nread * 1000 / 16);  /* ~16kHz sample rate */
        }
    }

  close(fd);
  g_voice.playing = false;

  syslog(LOG_INFO, TAG": Playback finished\n");
  return NULL;
}

/****************************************************************************
 * Name: audio_set_volume
 *
 * Description:
 *   Set the audio output volume.
 *
 ****************************************************************************/

static int audio_set_volume(uint8_t volume)
{
  struct audio_caps_desc_s cap_desc;
  int ret;

  if (g_voice.audio_fd < 0)
    {
      return -ENODEV;
    }

  memset(&cap_desc, 0, sizeof(cap_desc));
  cap_desc.caps.ac_format.hw = AUDIO_FU_VOLUME;
  cap_desc.caps.ac_controls.hw[0] = volume * 255 / 100;

  ret = ioctl(g_voice.audio_fd, AUDIOIOC_SETVOLUME,
              (unsigned long)&cap_desc);
  if (ret < 0)
    {
      syslog(LOG_WARNING, TAG": Set volume failed: %d\n", errno);
    }

  return ret;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int voice_alert_init(void)
{
  syslog(LOG_INFO, TAG": Initializing voice alert system\n");

  /* Initialize context */

  memset(&g_voice, 0, sizeof(g_voice));
  g_voice.initialized = false;
  g_voice.playing = false;
  g_voice.enabled = true;
  g_voice.volume = 80;
  g_voice.audio_fd = -1;
  pthread_mutex_init(&g_voice.lock, NULL);

  /* Open audio device */

  g_voice.audio_fd = open("/dev/audio/pcm0", O_WRONLY);
  if (g_voice.audio_fd < 0)
    {
      syslog(LOG_WARNING, TAG": Audio device not available: %d\n", errno);
      /* Non-fatal - voice will be simulated */
    }
  else
    {
      /* Set initial volume */

      audio_set_volume(g_voice.volume);
    }

  g_voice.initialized = true;

  syslog(LOG_INFO, TAG": Voice alert system initialized\n");
  return 0;
}

void voice_alert_deinit(void)
{
  syslog(LOG_INFO, TAG": Deinitializing voice alert system\n");

  /* Stop any playing voice */

  voice_alert_stop();

  g_voice.initialized = false;

  /* Close audio device */

  if (g_voice.audio_fd >= 0)
    {
      close(g_voice.audio_fd);
      g_voice.audio_fd = -1;
    }

  pthread_mutex_destroy(&g_voice.lock);
}

int voice_alert_play(uint8_t voice_id, uint8_t priority)
{
  pthread_attr_t attr;
  int ret;

  if (!g_voice.initialized || !g_voice.enabled)
    {
      return -ENODEV;
    }

  pthread_mutex_lock(&g_voice.lock);

  /* Check if higher priority playback is active */

  if (g_voice.playing && priority <= g_voice.current_priority)
    {
      pthread_mutex_unlock(&g_voice.lock);
      return -EBUSY;
    }

  /* Stop current playback */

  g_voice.playing = false;
  usleep(50000);  /* Let old task finish */

  /* Start new playback */

  g_voice.playing = true;
  g_voice.current_priority = priority;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 2048);

  ret = pthread_create(&g_voice.play_tid, &attr,
                       voice_play_task,
                       (FAR void *)(unsigned long)voice_id);
  if (ret != 0)
    {
      syslog(LOG_ERR, TAG": Failed to create play task: %d\n", ret);
      g_voice.playing = false;
    }

  pthread_mutex_unlock(&g_voice.lock);
  return ret;
}

void voice_alert_stop(void)
{
  g_voice.playing = false;
  if (g_voice.play_tid != 0)
    {
      pthread_join(g_voice.play_tid, NULL);
      g_voice.play_tid = 0;
    }
}

bool voice_alert_is_playing(void)
{
  return g_voice.playing;
}

void voice_alert_set_volume(uint8_t volume)
{
  if (volume > 100)
    {
      volume = 100;
    }

  g_voice.volume = volume;
  audio_set_volume(volume);
}

uint8_t voice_alert_get_volume(void)
{
  return g_voice.volume;
}

void voice_alert_enable(bool enable)
{
  g_voice.enabled = enable;
  if (!enable)
    {
      voice_alert_stop();
    }
}

bool voice_alert_is_enabled(void)
{
  return g_voice.enabled;
}

