/****************************************************************************
 * Name: create_main_screen
 *
 * Description:
 *   Create the main status display screen.
 *
 ****************************************************************************/

static void create_main_screen(void)
{
  lv_obj_t *scr = lv_obj_create(NULL);
  g_ui.main_screen = scr;

  /* Header bar */

  lv_obj_t *header = lv_obj_create(scr);
  lv_obj_set_size(header, SCREEN_WIDTH, HEADER_HEIGHT);
  lv_obj_align(header, LV_ALIGN_TOP_MID, 0, 0);
  lv_obj_set_style_bg_color(header, lv_color_hex(0x2196F3), 0);
  lv_obj_set_style_radius(header, 0, 0);

  g_ui.header_label = lv_label_create(header);
  lv_label_set_text(g_ui.header_label, "智锁卫士");
  lv_obj_set_style_text_color(g_ui.header_label, lv_color_white(), 0);
  lv_obj_align(g_ui.header_label, LV_ALIGN_CENTER, 0, 0);

  /* Status icons row */

  g_ui.ble_icon = lv_label_create(scr);
  lv_label_set_text(g_ui.ble_icon, LV_SYMBOL_BLUETOOTH);
  lv_obj_align(g_ui.ble_icon, LV_ALIGN_TOP_LEFT, 10, HEADER_HEIGHT + 5);
  lv_obj_set_style_text_color(g_ui.ble_icon, lv_color_hex(0x999999), 0);

  g_ui.radar_icon = lv_label_create(scr);
  lv_label_set_text(g_ui.radar_icon, LV_SYMBOL_EYE_OPEN);
  lv_obj_align(g_ui.radar_icon, LV_ALIGN_TOP_LEFT, 40, HEADER_HEIGHT + 5);
  lv_obj_set_style_text_color(g_ui.radar_icon, lv_color_hex(0x999999), 0);

  g_ui.battery_icon = lv_label_create(scr);
  lv_label_set_text(g_ui.battery_icon, LV_SYMBOL_BATTERY_FULL);
  lv_obj_align(g_ui.battery_icon, LV_ALIGN_TOP_RIGHT, -10,
               HEADER_HEIGHT + 5);
  lv_obj_set_style_text_color(g_ui.battery_icon,
                               lv_color_hex(0x4CAF50), 0);

  /* Door status display */

  lv_obj_t *status_container = lv_obj_create(scr);
  lv_obj_set_size(status_container, SCREEN_WIDTH - 20, 80);
  lv_obj_align(status_container, LV_ALIGN_TOP_MID, 0, CONTENT_Y + 30);
  lv_obj_set_style_bg_color(status_container, lv_color_hex(0xF5F5F5), 0);
  lv_obj_set_style_border_width(status_container, 0, 0);
  lv_obj_set_style_radius(status_container, 10, 0);

  g_ui.status_label = lv_label_create(status_container);
  lv_label_set_text(g_ui.status_label, "已锁");
  lv_obj_set_style_text_color(g_ui.status_label,
                               lv_color_hex(0x4CAF50), 0);
  lv_obj_set_style_text_font(g_ui.status_label, &lv_font_montserrat_28, 0);
  lv_obj_align(g_ui.status_label, LV_ALIGN_CENTER, 0, -10);

  /* Countdown display */

  g_ui.countdown_label = lv_label_create(scr);
  lv_label_set_text(g_ui.countdown_label, "");
  lv_obj_set_style_text_color(g_ui.countdown_label,
                               lv_color_hex(0xFF9800), 0);
  lv_obj_set_style_text_font(g_ui.countdown_label,
                              &lv_font_montserrat_24, 0);
  lv_obj_align(g_ui.countdown_label, LV_ALIGN_TOP_MID, 0,
               CONTENT_Y + 120);

  /* Footer info */

  lv_obj_t *footer = lv_label_create(scr);
  lv_label_set_text(footer, "WiFi: SmartLock-AP");
  lv_obj_set_style_text_color(footer, lv_color_hex(0x999999), 0);
  lv_obj_align(footer, LV_ALIGN_BOTTOM_MID, 0, -10);
}

/****************************************************************************
 * Name: create_countdown_screen
 *
 * Description:
 *   Create the countdown display screen.
 *
 ****************************************************************************/

static void create_countdown_screen(void)
{
  lv_obj_t *scr = lv_obj_create(NULL);
  g_ui.countdown_screen = scr;

  /* Large countdown number */

  lv_obj_t *countdown = lv_label_create(scr);
  lv_label_set_text(countdown, "30");
  lv_obj_set_style_text_color(countdown, lv_color_hex(0xFF5722), 0);
  lv_obj_set_style_text_font(countdown, &lv_font_montserrat_48, 0);
  lv_obj_align(countdown, LV_ALIGN_CENTER, 0, -20);

  /* Label */

  lv_obj_t *label = lv_label_create(scr);
  lv_label_set_text(label, "秒后自动关门");
  lv_obj_set_style_text_color(label, lv_color_hex(0x666666), 0);
  lv_obj_align(label, LV_ALIGN_CENTER, 0, 30);

  /* Progress bar */

  lv_obj_t *bar = lv_bar_create(scr);
  lv_obj_set_size(bar, SCREEN_WIDTH - 40, 20);
  lv_obj_align(bar, LV_ALIGN_CENTER, 0, 60);
  lv_bar_set_range(bar, 0, 100);
  lv_bar_set_value(bar, 100, LV_ANIM_ON);
  lv_obj_set_style_bg_color(bar, lv_color_hex(0xE0E0E0), 0);
  lv_obj_set_style_bg_color(bar, lv_color_hex(0xFF5722),
                            LV_PART_INDICATOR);
