/****************************************************************************
 * Name: alert_timer_cb
 *
 * Description:
 *   Timer callback to hide alert after duration.
 *
 ****************************************************************************/

static void alert_timer_cb(lv_timer_t *timer)
{
  ui_manager_hide_alert();
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int ui_manager_init(void)
{
  syslog(LOG_INFO, TAG": Initializing UI manager\n");

  /* Initialize context */

  memset(&g_ui, 0, sizeof(g_ui));
  g_ui.initialized = false;
  g_ui.brightness = 80;
  pthread_mutex_init(&g_ui.lock, NULL);

  /* Initialize LVGL */

  lv_init();

  /* Create screens */

  create_main_screen();
  create_countdown_screen();
  create_alert_screen();

  /* Show main screen */

  lv_scr_load(g_ui.main_screen);
  g_ui.current_screen = UI_SCREEN_MAIN;

  g_ui.initialized = true;

  syslog(LOG_INFO, TAG": UI manager initialized\n");
  return 0;
}

void ui_manager_deinit(void)
{
  syslog(LOG_INFO, TAG": Deinitializing UI manager\n");

  g_ui.initialized = false;

  /* Delete alert timer */

  if (g_ui.alert_timer != NULL)
    {
      lv_timer_del(g_ui.alert_timer);
      g_ui.alert_timer = NULL;
    }

  pthread_mutex_destroy(&g_ui.lock);
}

void ui_manager_update(FAR const struct ui_data_s *data)
{
  if (!g_ui.initialized || data == NULL)
    {
      return;
    }

  pthread_mutex_lock(&g_ui.lock);

  /* Update BLE icon */

  if (data->ble_connected)
    {
      lv_obj_set_style_text_color(g_ui.ble_icon,
                                   lv_color_hex(0x2196F3), 0);
    }
  else
    {
      lv_obj_set_style_text_color(g_ui.ble_icon,
                                   lv_color_hex(0x999999), 0);
    }

  /* Update radar icon */

  if (data->radar_status)
    {
      lv_obj_set_style_text_color(g_ui.radar_icon,
                                   lv_color_hex(0x4CAF50), 0);
    }
  else
    {
      lv_obj_set_style_text_color(g_ui.radar_icon,
                                   lv_color_hex(0x999999), 0);
    }

  /* Update battery icon */

  if (data->battery_level > 75)
    {
      lv_label_set_text(g_ui.battery_icon, LV_SYMBOL_BATTERY_FULL);
      lv_obj_set_style_text_color(g_ui.battery_icon,
                                   lv_color_hex(0x4CAF50), 0);
    }
  else if (data->battery_level > 50)
    {
      lv_label_set_text(g_ui.battery_icon, LV_SYMBOL_BATTERY_3);
      lv_obj_set_style_text_color(g_ui.battery_icon,
                                   lv_color_hex(0xFFC107), 0);
    }
  else if (data->battery_level > 25)
    {
      lv_label_set_text(g_ui.battery_icon, LV_SYMBOL_BATTERY_2);
      lv_obj_set_style_text_color(g_ui.battery_icon,
                                   lv_color_hex(0xFF9800), 0);
    }
  else
    {
      lv_label_set_text(g_ui.battery_icon, LV_SYMBOL_BATTERY_1);
      lv_obj_set_style_text_color(g_ui.battery_icon,
                                   lv_color_hex(0xF44336), 0);
    }

  /* Update door status */

  switch (data->door_state)
    {
      case 0:  /* Closed */
        lv_label_set_text(g_ui.status_label, "已关闭");
        lv_obj_set_style_text_color(g_ui.status_label,
                                     lv_color_hex(0x4CAF50), 0);
        break;

      case 1:  /* Open */
        lv_label_set_text(g_ui.status_label, "已打开");
        lv_obj_set_style_text_color(g_ui.status_label,
                                     lv_color_hex(0xFF9800), 0);
        break;

      case 2:  /* Closing */
        lv_label_set_text(g_ui.status_label, "关闭中...");
        lv_obj_set_style_text_color(g_ui.status_label,
                                     lv_color_hex(0x2196F3), 0);
        break;

      case 3:  /* Locked */
        lv_label_set_text(g_ui.status_label, "已锁定");
        lv_obj_set_style_text_color(g_ui.status_label,
                                     lv_color_hex(0x4CAF50), 0);
        break;
    }

  /* Update countdown */

  if (data->countdown_sec > 0)
    {
      char countdown_text[16];
      snprintf(countdown_text, sizeof(countdown_text), "%d秒",
               data->countdown_sec);
      lv_label_set_text(g_ui.countdown_label, countdown_text);
    }
  else
    {
      lv_label_set_text(g_ui.countdown_label, "");
    }

  /* Update status text */

  if (data->status_text[0] != '\0')
    {
      lv_obj_t *footer = lv_obj_get_child(g_ui.main_screen, -1);
      if (footer != NULL)
        {
          lv_label_set_text(footer, data->status_text);
        }
    }

  pthread_mutex_unlock(&g_ui.lock);
}

void ui_manager_set_screen(uint8_t screen_id, uint8_t anim_type)
{
  if (!g_ui.initialized)
    {
      return;
    }

  lv_obj_t *screen = NULL;

  switch (screen_id)
    {
      case UI_SCREEN_MAIN:
        screen = g_ui.main_screen;
        break;
      case UI_SCREEN_COUNTDOWN:
        screen = g_ui.countdown_screen;
        break;
      case UI_SCREEN_ALERT:
        screen = g_ui.alert_screen;
        break;
      default:
        return;
    }

  if (screen == NULL)
    {
      return;
    }

  pthread_mutex_lock(&g_ui.lock);

  /* Apply animation */

  switch (anim_type)
    {
      case UI_ANIM_FADE:
        lv_scr_load_anim(screen, LV_SCR_LOAD_ANIM_FADE_ON, 300, 0, false);
        break;
      case UI_ANIM_SLIDE:
        lv_scr_load_anim(screen, LV_SCR_LOAD_ANIM_MOVE_LEFT, 300, 0,
                         false);
        break;
      default:
        lv_scr_load(screen);
        break;
    }

  g_ui.current_screen = screen_id;

  pthread_mutex_unlock(&g_ui.lock);
}

void ui_manager_show_alert(FAR const char *message, uint16_t color,
                           uint32_t duration_ms)
{
  if (!g_ui.initialized)
    {
      return;
    }

  pthread_mutex_lock(&g_ui.lock);

  /* Update alert text */

  lv_label_set_text(g_ui.alert_label, message);

  /* Update alert color */

  lv_obj_set_style_bg_color(g_ui.alert_container,
                             lv_color_hex(color), 0);

  /* Show alert screen */

  lv_scr_load(g_ui.alert_screen);
  g_ui.current_screen = UI_SCREEN_ALERT;

  /* Set timer to hide */

  if (g_ui.alert_timer != NULL)
    {
      lv_timer_del(g_ui.alert_timer);
    }

  if (duration_ms > 0)
    {
      g_ui.alert_timer = lv_timer_create(alert_timer_cb,
                                         duration_ms, NULL);
      lv_timer_set_repeat_count(g_ui.alert_timer, 1);
    }

  pthread_mutex_unlock(&g_ui.lock);
}

void ui_manager_hide_alert(void)
{
  if (!g_ui.initialized)
    {
      return;
    }

  pthread_mutex_lock(&g_ui.lock);

  /* Return to main screen */

  lv_scr_load(g_ui.main_screen);
