// agent_tools.c - Tool实现

#include "radar_driver.h"
#include "door_sensor.h"
#include "door_control.h"

// Tool: radar_check
int tool_radar_check(int argc, char **argv)
{
    struct radar_result_s result;

    if (radar_get_latest(&result) == 0)
    {
        printf("{\"presence\": %s, \"zone\": %d, \"distance\": %d}\n",
               result.state != RADAR_STATE_NO_TARGET ? "true" : "false",
               result.zone,
               result.distance_cm);
        return 0;
    }

    printf("{\"error\": \"no data\"}\n");
    return -1;
}

// Tool: door_sensor_read
int tool_door_sensor_read(int argc, char **argv)
{
    struct door_status_s status;

    if (door_sensor_get_status(&status) == 0)
    {
        printf("{\"closed\": %s, \"locked\": %s}\n",
               status.door_state == DOOR_STATE_CLOSED ? "true" : "false",
               status.lock_state == LOCK_STATE_LOCKED ? "true" : "false");
        return 0;
    }

    printf("{\"error\": \"read failed\"}\n");
    return -1;
}

// Tool: motor_control
int tool_motor_control(int argc, char **argv)
{
    if (argc < 2)
    {
        printf("{\"error\": \"missing action\"}\n");
        return -1;
    }

    uint8_t cmd;
    if (strcmp(argv[1], "open") == 0)
        cmd = MOTOR_CMD_OPEN;
    else if (strcmp(argv[1], "close") == 0)
        cmd = MOTOR_CMD_CLOSE;
    else if (strcmp(argv[1], "lock") == 0)
        cmd = MOTOR_CMD_LOCK;
    else if (strcmp(argv[1], "unlock") == 0)
        cmd = MOTOR_CMD_UNLOCK;
    else if (strcmp(argv[1], "stop") == 0)
        cmd = MOTOR_CMD_STOP;
    else
    {
        printf("{\"error\": \"invalid action\"}\n");
        return -1;
    }

    int ret = door_control_execute(cmd);
    printf("{\"success\": %s}\n", ret == 0 ? "true" : "false");
    return ret;
}

// Tool: set_timeout
int tool_set_timeout(int argc, char **argv)
{
    if (argc < 2)
    {
        printf("{\"error\": \"missing timeout\"}\n");
        return -1;
    }

    int timeout = atoi(argv[1]);
    if (timeout < 5 || timeout > 300)
    {
        printf("{\"error\": \"timeout out of range\"}\n");
        return -1;
    }

    // 设置超时
    extern uint32_t g_door_open_timeout_ms;
    g_door_open_timeout_ms = timeout * 1000;

    printf("{\"success\": true, \"timeout\": %d}\n", timeout);
    return 0;
}
