  import ble from '../lib/ble.js';

  export default {
    data: {
      bleStatus: '未连接',
      doorStatus: '已关闭',
      lockStatus: '已锁定',
      doorIcon: '/assets/door_closed.png',
      showCountdown: false,
      countdown: 30,
      connected: false
