/****************************************************************************
 * Name: tool_radar_check
 *
 * Description:
 *   Tool function for ai_agent to check radar status.
 *   Output: JSON with radar detection data.
 *
 *   Usage from ai_agent:
 *     ask "查看雷达状态"
 *     ask "是否检测到人"
 *
 ****************************************************************************/

int tool_radar_check(int argc, char **argv)
{
  struct radar_result_s result;
  int ret;

  ret = radar_get_latest(&result);
  if (ret == 0)
    {
      printf("{\"presence\": %s, \"zone\": %d, \"distance\": %d, "
             "\"energy\": %d, \"state\": %d}\n",
             result.state != RADAR_STATE_NO_TARGET ? "true" : "false",
             result.zone,
             result.distance_cm,
             result.energy,
             result.state);
      return 0;
    }

  printf("{\"error\": \"no_data\", \"message\": \"雷达数据不可用\"}\n");
  return -1;
}

/****************************************************************************
 * Name: tool_door_sensor_read
 *
 * Description:
 *   Tool function for ai_agent to read door sensor status.
 *   Output: JSON with door state.
 *
 *   Usage from ai_agent:
 *     ask "门是开的还是关的"
 *     ask "查看门锁状态"
 *
 ****************************************************************************/

int tool_door_sensor_read(int argc, char **argv)
{
  struct door_status_s status;
  int ret;

  ret = door_sensor_get_status(&status);
  if (ret == 0)
    {
      printf("{\"closed\": %s, \"locked\": %s, "
             "\"door_state\": %d, \"lock_state\": %d}\n",
             status.door_state == DOOR_STATE_CLOSED ? "true" : "false",
             status.lock_state == LOCK_STATE_LOCKED ? "true" : "false",
             status.door_state,
             status.lock_state);
      return 0;
    }

  printf("{\"error\": \"read_failed\", \"message\": \"读取门磁失败\"}\n");
  return -1;
}

/****************************************************************************
 * Name: tool_motor_control
 *
 * Description:
 *   Tool function for ai_agent to control door motor.
 *   Input: action = "open"|"close"|"lock"|"unlock"|"stop"
 *   Output: JSON with operation result.
 *
 *   Usage from ai_agent:
 *     ask "关门"
 *     ask "锁门"
 *     ask "停止电机"
 *
 ****************************************************************************/

int tool_motor_control(int argc, char **argv)
{
  uint8_t cmd;
  int ret;

  if (argc < 2)
    {
      printf("{\"error\": \"missing_action\", "
             "\"message\": \"缺少动作参数\"}\n");
      return -1;
    }

  /* Parse action */

  if (strcmp(argv[1], "open") == 0)
    {
      cmd = MOTOR_CMD_OPEN;
    }
  else if (strcmp(argv[1], "close") == 0)
    {
      cmd = MOTOR_CMD_CLOSE;
    }
  else if (strcmp(argv[1], "lock") == 0)
    {
      cmd = MOTOR_CMD_LOCK;
    }
  else if (strcmp(argv[1], "unlock") == 0)
    {
      cmd = MOTOR_CMD_UNLOCK;
    }
  else if (strcmp(argv[1], "stop") == 0)
    {
      cmd = MOTOR_CMD_STOP;
    }
  else
    {
      printf("{\"error\": \"invalid_action\", "
             "\"message\": \"无效的动作: %s\"}\n", argv[1]);
      return -1;
    }

  /* Execute command */

  ret = door_control_execute(cmd);
  if (ret == 0)
    {
      printf("{\"success\": true, \"action\": \"%s\"}\n", argv[1]);
      return 0;
    }
  else if (ret == -EBUSY)
    {
      printf("{\"success\": false, \"error\": \"motor_busy\", "
             "\"message\": \"电机正在运行中\"}\n");
    }
  else
    {
      printf("{\"success\": false, \"error\": \"execute_failed\", "
             "\"message\": \"执行失败: %d\"}\n", ret);
    }

  return ret;
}

/****************************************************************************
 * Name: tool_set_timeout
 *
 * Description:
 *   Tool function for ai_agent to set auto-close timeout.
 *   Input: seconds = 5-300
 *   Output: JSON with result.
 *
 *   Usage from ai_agent:
 *     ask "设置关门时间60秒"
 *     ask "30秒后自动关门"
 *
 ****************************************************************************/

int tool_set_timeout(int argc, char **argv)
{
  extern uint32_t g_door_open_timeout_ms;
  int timeout;

  if (argc < 2)
    {
      printf("{\"error\": \"missing_timeout\", "
             "\"message\": \"缺少超时参数\"}\n");
      return -1;
    }

  timeout = atoi(argv[1]);
  if (timeout < 5 || timeout > 300)
    {
      printf("{\"error\": \"out_of_range\", "
             "\"message\": \"超时范围: 5-300秒\"}\n");
      return -1;
    }

  g_door_open_timeout_ms = (uint32_t)(timeout * 1000);

  printf("{\"success\": true, \"timeout\": %d}\n", timeout);
  return 0;
}

