  if (radar_ok)
    {
      printf("    \"state\": %d,\n", radar.state);
      printf("    \"zone\": %d,\n", radar.zone);
      printf("    \"distance\": %d\n", radar.distance_cm);
    }
  printf("  },\n");

  printf("  \"door\": {\n");
