/**
 * 智锁卫士 - BLE通信模块
 * Smart Lock Guardian - BLE Communication Module
 *
 * 封装BLE扫描、连接、读写、通知功能
 */

// BLE服务UUID
const SERVICE_UUID = '00001820-0000-1000-8000-00805f9b34fb'

// 特征UUID
const CHAR_DOOR_STATE = '00002b20-0000-1000-8000-00805f9b34fb'    // 门状态(读+通知)
const CHAR_DOOR_CONTROL = '00002b21-0000-1000-8000-00805f9b34fb'  // 门控制(写)
const CHAR_CONFIG = '00002b22-0000-1000-8000-00805f9b34fb'        // 配置(读写)
const CHAR_NOTIFICATION = '00002b23-0000-1000-8000-00805f9b34fb'  // 通知(通知)

/**
 * BLE管理类
 */
class BLEManager {
  constructor() {
    this.deviceId = null
    this.connected = false
    this.onDeviceFound = null
    this.onDataReceived = null
    this.onConnectionChange = null
    this.scanTimer = null
  }

  /**
   * 初始化BLE
   */
  init() {
    return new Promise((resolve, reject) => {
      // 检查BLE是否可用
      if (typeof ble === 'undefined') {
        reject(new Error('BLE not available'))
        return
      }

      ble.initialize({
        success: () => {
          console.log('BLE initialized successfully')
          resolve()
        },
        fail: (err) => {
          console.error('BLE init failed:', err)
          reject(err)
        }
      })
    })
  }

  /**
   * 开始扫描
   */
  startScan() {
    return new Promise((resolve, reject) => {
      ble.startScan({
        services: [SERVICE_UUID],
        interval: 5000,  // 5秒扫描间隔
        success: (devices) => {
          console.log('Found devices:', devices.length)
          devices.forEach(device => {
            if (this.onDeviceFound) {
              this.onDeviceFound(device)
            }
          })
          resolve()
        },
        fail: (err) => {
          console.error('Scan failed:', err)
          reject(err)
        }
      })
    })
  }

  /**
   * 停止扫描
   */
  stopScan() {
    return new Promise((resolve, reject) => {
      ble.stopScan({
        success: () => {
          console.log('Scan stopped')
          resolve()
        },
        fail: (err) => {
          console.error('Stop scan failed:', err)
          reject(err)
        }
      })
    })
  }

  /**
   * 连接设备
   */
  connect(deviceId) {
    return new Promise((resolve, reject) => {
      this.deviceId = deviceId

      ble.connect({
        deviceId: deviceId,
        success: () => {
          console.log('Connected to device:', deviceId)
          this.connected = true
          if (this.onConnectionChange) {
            this.onConnectionChange(true)
          }
          resolve()
        },
        fail: (err) => {
          console.error('Connection failed:', err)
          this.connected = false
          reject(err)
        }
      })
    })
  }

  /**
   * 断开连接
   */
  disconnect() {
    if (!this.deviceId) return

    return new Promise((resolve, reject) => {
      ble.closeBLEConnection({
        deviceId: this.deviceId,
        success: () => {
          console.log('Disconnected')
          this.connected = false
          this.deviceId = null
          if (this.onConnectionChange) {
            this.onConnectionChange(false)
          }
          resolve()
        },
        fail: (err) => {
          console.error('Disconnect failed:', err)
          reject(err)
        }
      })
    })
  }

  /**
   * 订阅通知
   */
  subscribe() {
    if (!this.deviceId || !this.connected) {
      return Promise.reject(new Error('Not connected'))
    }

    return new Promise((resolve, reject) => {
      // 订阅门状态通知
      ble.notifyBLECharacteristicValueChange({
        deviceId: this.deviceId,
        serviceId: SERVICE_UUID,
        characteristicId: CHAR_NOTIFICATION,
        state: true,
        success: () => {
          console.log('Subscribed to notifications')

          // 监听数据变化
          ble.onBLECharacteristicValueChange = (res) => {
            if (this.onDataReceived) {
              const data = new Uint8Array(res.value)
              this.onDataReceived(data)
            }
          }

          resolve()
        },
        fail: (err) => {
          console.error('Subscribe failed:', err)
          reject(err)
        }
      })
    })
  }

  /**
   * 取消订阅
   */
  unsubscribe() {
    if (!this.deviceId) return

    return new Promise((resolve, reject) => {
      ble.notifyBLECharacteristicValueChange({
        deviceId: this.deviceId,
        serviceId: SERVICE_UUID,
        characteristicId: CHAR_NOTIFICATION,
        state: false,
        success: () => {
          console.log('Unsubscribed')
          resolve()
        },
        fail: (err) => {
          console.error('Unsubscribe failed:', err)
          reject(err)
        }
      })
    })
  }

  /**
   * 写入数据
   */
  write(data) {
    if (!this.deviceId || !this.connected) {
      return Promise.reject(new Error('Not connected'))
    }

    return new Promise((resolve, reject) => {
      ble.writeBLECharacteristicValue({
        deviceId: this.deviceId,
        serviceId: SERVICE_UUID,
        characteristicId: CHAR_DOOR_CONTROL,
        value: new Uint8Array(data).buffer,
        success: () => {
          console.log('Data written:', data)
          resolve()
        },
        fail: (err) => {
          console.error('Write failed:', err)
          reject(err)
        }
      })
    })
  }

  /**
   * 读取门状态
   */
  readDoorState() {
    if (!this.deviceId || !this.connected) {
      return Promise.reject(new Error('Not connected'))
    }

    return new Promise((resolve, reject) => {
      ble.readBLECharacteristicValue({
        deviceId: this.deviceId,
        serviceId: SERVICE_UUID,
        characteristicId: CHAR_DOOR_STATE,
        success: (res) => {
          const data = new Uint8Array(res.value)
          resolve({
            doorState: data[0],
            lockState: data[1]
          })
        },
        fail: (err) => {
          console.error('Read failed:', err)
          reject(err)
        }
      })
    })
  }

  /**
   * 写入配置
   */
  writeConfig(config) {
    if (!this.deviceId || !this.connected) {
      return Promise.reject(new Error('Not connected'))
    }

    const data = [
      config.timeout || 30,
      config.volume || 80,
      config.brightness || 80
    ]

    return new Promise((resolve, reject) => {
      ble.writeBLECharacteristicValue({
        deviceId: this.deviceId,
        serviceId: SERVICE_UUID,
        characteristicId: CHAR_CONFIG,
        value: new Uint8Array(data).buffer,
        success: () => {
          console.log('Config written:', config)
          resolve()
        },
        fail: (err) => {
          console.error('Write config failed:', err)
          reject(err)
        }
      })
    })
  }

  /**
   * 获取连接状态
   */
  isConnected() {
    return this.connected
  }

  /**
   * 获取设备ID
   */
  getDeviceId() {
    return this.deviceId
  }
}

// 导出单例
export default new BLEManager()

