/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <stdint.h>
#include <stdbool.h>

/* 子模块接口 */

#include "radar_driver.h"   /* 底层雷达驱动：radar_driver_result_t / radar_driver_get_status() */
#include "door_sensor.h"    /* 门磁传感器：door_sensor_init() / door_sensor_get_status()        */
#include "door_control.h"   /* 电机与蜂鸣器：motor_control() / MOTOR_CMD_*                       */
#include "safety.h"         /* 防夹安全：应用级 radar_result_t / radar_get_status()             */

/****************************************************************************
 * BLE 服务接口 (src/ble_service.c)
 ****************************************************************************/

int     ble_service_init(void);
int     ble_start_advertising(void);
int     ble_stop_advertising(void);
int     ble_notify_door_state(uint8_t state);
int     process_ble_command(uint8_t cmd);

/**
 * @brief 查询 BLE 当前是否有活动连接
 *
 * 该函数被 agent_tools.c 调用，但此前从未实现，导致链接失败。
 *
 * @return true 已连接, false 未连接
 */

bool    ble_is_connected(void);

/**
 * @brief 获取当前门状态
 *
 * @return uint8_t 0: 关闭, 1: 开启
 */

uint8_t get_door_state(void);

/****************************************************************************
 * 应用入口 (src/smart_lock_main.c)
 ****************************************************************************/

int smart_lock_main(int argc, char *argv[]);

#endif /* __APP_SMART_LOCK_INCLUDE_SMART_LOCK_H */

/**
 * @file safety.h
 * @brief 安全模块头文件（应用级雷达视图 + 防夹保护）
 *
 * 本文件定义了防夹保护功能的接口和数据结构。
 *
 * 集成修复说明（2026-09-18）：
 *   原版本在此处重复定义了 radar_result_t / radar_state_t，与
 *   radar_driver.h 中的同名类型字段布局完全不同，两个头文件一旦被同一
 *   个翻译单元包含即编译失败。现明确划分为两层：
 *
 *     radar_driver.h  —— 底层驱动原始读数  radar_driver_result_t
 *     safety.h        —— 应用级雷达视图    radar_result_t（本文件）
 *
 *   同时补上 agent_tools.c 依赖的 zone / distance 字段。
 *   另外原文件末尾重复声明了 radar_get_status()，与 radar_driver.c 中的
 *   全局符号冲突；底层驱动的对应函数已更名为 radar_driver_get_status()。
 *
 * Copyright (C) 2026 weihedui Team
 * Licensed under the Apache License, Version 2.0
 */

#ifndef __SAFETY_H__
#define __SAFETY_H__

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/**
 * @brief 雷达区域定义（应用级）
 */
typedef enum {
    RADAR_ZONE_INDOOR = 0,    /**< 室内侧 */
    RADAR_ZONE_OUTDOOR        /**< 室外侧 */
} radar_zone_t;

/**
 * @brief 雷达状态定义（应用级）
 */
typedef enum {
    RADAR_STATE_NO_TARGET = 0, /**< 无目标 */
    RADAR_STATE_MOVING,        /**< 目标移动中 */
    RADAR_STATE_STATIONARY     /**< 目标静止 */
} radar_state_t;

/**
 * @brief 雷达数据结构体（应用级）
 *
 * 注意：这是"应用级"视图，与底层驱动的 radar_driver_result_t 是两层
 * 不同的数据模型，命名刻意区分以避免符号冲突。
 */
typedef struct {
    radar_state_t state;      /**< 雷达状态 */
    radar_zone_t  zone;       /**< 区域（室内/室外） */
    uint16_t      distance;   /**< 距离（厘米） */
    uint16_t      energy;     /**< 能量值 */
    uint32_t      timestamp;  /**< 时间戳 */
} radar_result_t;

/**
 * @brief 安全配置结构体
 */
typedef struct {
    uint8_t anti_pinch_threshold;  /**< 防夹检测阈值（连续检测次数） */
    uint32_t check_interval_ms;    /**< 检测间隔（毫秒） */
    uint16_t detection_range_cm;   /**< 检测范围（厘米） */
} safety_config_t;

/**
 * @brief 初始化安全模块
 *
 * @param config 安全配置参数
 * @return int 0: 成功, -1: 失败
 */
int safety_init(const safety_config_t *config);

/**
 * @brief 反初始化安全模块
 *
 * @return int 0: 成功, -1: 失败
 */
int safety_deinit(void);

/**
 * @brief 启动防夹检测
 *
 * @return int 0: 成功, -1: 失败
 */
int safety_start(void);

/**
 * @brief 停止防夹检测
 *
 * @return int 0: 成功, -1: 失败
 */
int safety_stop(void);

/**
 * @brief 获取雷达状态（应用级）
 *
 * @param result 雷达数据输出
 * @return int 0: 成功, -1: 失败
 */
int radar_get_status(radar_result_t *result);

/**
 * @brief 检查是否触发防夹保护
 *
 * @return true: 触发防夹保护, false: 未触发
 */
bool safety_is_anti_pinch_triggered(void);

/**
 * @brief 重置防夹检测状态
 */
void safety_reset(void);

#ifdef __cplusplus
}
#endif

#endif /* __SAFETY_H__ */

/****************************************************************************
 * app/smart_lock/src/smart_lock_main.c
 *
 * 智锁卫士 - 应用入口
 *
 * 此前整个工程没有任何 main() 入口：6 个模块各自提供 xxx_init()，但无人
 * 调用，因此即使编译通过也不会运行。本文件补齐应用入口。
 *
 * Copyright (C) 2026 weihedui (Team 296)
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <stdio.h>
#include <unistd.h>

#include "smart_lock.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* 默认硬件配置
 *
 * TODO(团队): 以下 GPIO 引脚号为占位值，需按黄山派 SF32LB52 实际接线确认。
 */

static const motor_config_t g_default_motor_config =
{
  .open_gpio_pin    = 0,
  .close_gpio_pin   = 0,
  .lock_gpio_pin    = 0,
  .buzzer_gpio_pin  = 0,
  .open_timeout_ms  = 3000,
  .close_timeout_ms = 3000,
  .lock_timeout_ms  = 2000,
};

static const safety_config_t g_default_safety_config =
{
  .anti_pinch_threshold = 3,
  .check_interval_ms    = 100,
  .detection_range_cm   = 50,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/**
 * @brief 智锁卫士主入口
 */

int smart_lock_main(int argc, char *argv[])
{
  int ret;

  (void)argc;
  (void)argv;

  printf("[smart_lock] =====================================\n");
  printf("[smart_lock] 智锁卫士启动 (Team 296 weihedui)\n");
  printf("[smart_lock] =====================================\n");

  ret = radar_init();
  printf("[smart_lock] radar_init            -> %d\n", ret);

  ret = door_sensor_init();
  printf("[smart_lock] door_sensor_init      -> %d\n", ret);

  ret = door_control_init(&g_default_motor_config);
  printf("[smart_lock] door_control_init     -> %d\n", ret);

  ret = safety_init(&g_default_safety_config);
  printf("[smart_lock] safety_init           -> %d\n", ret);

  ret = safety_start();
  printf("[smart_lock] safety_start          -> %d\n", ret);

  ret = ble_service_init();
  printf("[smart_lock] ble_service_init      -> %d\n", ret);

  ret = ble_start_advertising();
  printf("[smart_lock] ble_start_advertising -> %d\n", ret);

  printf("[smart_lock] 初始化完成，进入主循环\n");

  /* 主循环：各子模块的工作负载都在自己的 pthread 里跑，这里只负责保活 */

  for (;;)
    {
      sleep(5);
    }

  return 0;
}

/**
 * @brief NuttX 应用入口
 *
 * nuttx_add_application / Application.mk 约定的入口符号为 main()。
 */

int main(int argc, char *argv[])
{
  return smart_lock_main(argc, argv);
}

