{
    printf("BLE: [stub] advertising not started\n");
    return 0;
}

int ble_stop_advertising(void)
{
    printf("BLE: [stub] advertising already stopped\n");
    return 0;
}

int ble_notify_door_state(uint8_t state)
{
    door_state_stub = state;

    if (!notify_enabled_stub)
    {
        return -ENOTCONN;
    }

