  $ms = New-Object System.IO.MemoryStream
  $dl = (Get-Date).AddSeconds($sec)
  while ((Get-Date) -lt $dl) {
    try { $a = $sp.BytesToRead; if ($a -gt 0) { $n = $sp.Read($buf,0,[Math]::Min($buf.Length,$a)); $ms.Write($buf,0,$n) } } catch {}
    Start-Sleep -Milliseconds 10
  }
  return [System.Text.Encoding]::ASCII.GetString($ms.ToArray())
}

Write-Output "===== 等待排队中的 I2C 扫描跑完（最多 240 秒） ====="
$t0 = Get-Date
$got = $false
while (((Get-Date) - $t0).TotalSeconds -lt 240) {
  $chunk = ReadFor 5
  if ($chunk -match 'nsh>') { $got = $true; break }
}
Write-Output ("  等待 {0:N0} 秒, 提示符出现: {1}" -f ((Get-Date)-$t0).TotalSeconds, $got)

if (-not $got) {
  Write-Output "  再探一次..."
  $sp.Write("`r`n"); $p = ReadFor 8
  Write-Output ("  [" + ($p -replace "`r","<CR>" -replace "`n","<LF>") + "]")
  $got = $p -match 'nsh>'
}

if ($got) {
  Write-Output ""
  Write-Output "=================== nsh> smart_lock （40 秒） ==================="
  $sp.Write("smart_lock`r`n")
  $o = ReadFor 40
  Write-Output $(if ($o.Trim().Length -eq 0) { "  (无输出)" } else { ($o -replace "`r","<CR>" -replace "`n","<LF>`n") })
  Write-Output ""
  $sp.Write([char]3); Start-Sleep -Milliseconds 600; $sp.Write("`r`n")
  Write-Output "--- Ctrl-C 后 ---"
  Write-Output (ReadFor 6)
} else {
  Write-Output "  提示符仍未回来。"
}
$sp.Close()
Write-Output "串口已关闭。"

