    BSP_LCD_Reset(1);
    LCD_DRIVER_DELAY_MS(120);

    LCD_WriteReg(hlcdc, 0x01, (uint8_t *)NULL, 0);
    LCD_DRIVER_DELAY_MS(120);

    /* ReadID is informational only - some panels do not respond reliably
