      /* Turn on the display */

      if (priv->p_drv_ops && priv->p_drv_ops->p_ops &&
          priv->p_drv_ops->p_ops->DisplayOn)
        {
          priv->p_drv_ops->p_ops->DisplayOn(&priv->hlcdc);
