728	static int lcd_hw_setup_thread_entry(int argc, FAR char *argv[])
729	{
730	    lcd_drv_desc_t *p_drv_ops = s_drv_lcd.p_drv_ops;
731	  int ret;
732	  int retry;
733	
734	#if defined(CONFIG_VIDEO_FB) && defined(CONFIG_LCD_FRAMEBUFFER)
735	    /* Register /dev/fb0 first so node creation is not blocked by panel init. */
736	    for (retry = 0; retry < 30; retry++)
737	      {
738	        s_fb_registering = true;
739	        ret = fb_register(0, 0);
740	        s_fb_registering = false;
741	
742	        if (ret == OK || ret == -EEXIST)
743	          {
744	            lcdinfo("fb_register done.\n");
745	            break;
746	          }
747	
748	        if (ret != -ENOENT && ret != -ENODEV && ret != -EBUSY)
749	          {
750	            syslog(LOG_ERR, "ERROR: fb_register() failed: %d\n", ret);
751	            break;
752	          }
753	
754	        usleep(100 * 1000);
755	      }
756	#endif
757	
758	    if (p_drv_ops && p_drv_ops->p_ops && p_drv_ops->p_ops->Init)
759	    {
760	        p_drv_ops->p_ops->Init(&s_drv_lcd.hlcdc);
761	    }
762	
763	#ifdef SOC_BF0_HCPU     /* gpio1 only work on hcpu */
764	    irq_attach(NX_IRQ(LCDC1_IRQn), lcdc1_isr, (void *)&s_drv_lcd.hlcdc);
765	    up_enable_irq(NX_IRQ(LCDC1_IRQn));
766	#endif /* SOC_BF0_HCPU */
767	
768	    HAL_LCDC_SetBgColor(&s_drv_lcd.hlcdc, 0, 0, 0);
769	    HAL_LCDC_LayerReset(&s_drv_lcd.hlcdc, HAL_LCDC_LAYER_DEFAULT);
770	    HAL_LCDC_LayerSetFormat(&s_drv_lcd.hlcdc, HAL_LCDC_LAYER_DEFAULT,
771	                            LCDC_PIXEL_FORMAT_RGB565);
772	
773	    s_lcd_hw_ready = true;
774	
775	    return OK;
776	}
