778	static int lcd_init_thread_entry(int argc, FAR char *argv[])
779	{
780		lcd_drv_desc_t *p_drv_ops;
781	  int ret;
782	  int hw_pid;
783	  bool lcd_registered = false;
784	  int retry;
785	
786		BSP_LCD_PowerUp();
787		
788		p_drv_ops = find_right_driver();
789	
790	#ifdef CONFIG_LCD_USING_CO5300
791	  if (!p_drv_ops)
792	  {
793	    p_drv_ops = (lcd_drv_desc_t *)&__lcddriver_co5300;
794	  }
795	#endif
796	
797	#ifdef CONFIG_LCD_USING_ILI8688E
798	  if (!p_drv_ops)
799	  {
800	    p_drv_ops = (lcd_drv_desc_t *)&__lcddriver_ili8688e;
801	  }
802	#endif
803	
804		if (p_drv_ops)
805		{
806	    lcdinfo("Init LCD %s", p_drv_ops->name);
807	
808			switch(p_drv_ops->p_init_cfg->color_mode)
809			{
810			   case LCDC_PIXEL_FORMAT_RGB565:
811				 s_drv_lcd.bpp = 16;
812				 break;
813			
814			   case LCDC_PIXEL_FORMAT_RGB888:
815				 s_drv_lcd.bpp = 24;
816				 break;
817				 
818	         default:
819	       s_drv_lcd.bpp = 16;
820	       lcdwarn("Unknown color mode %d, fallback to RGB565",
821	               p_drv_ops->p_init_cfg->color_mode);
822	       break;
823			 }
824	
825	  /* Keep framebuffer format aligned with panel color mode (typically RGB565)
826	   * so fb writes are sent without intermediate color conversion.
827	   */
828	
829		}
830	
831		/* If find_right_driver fell back without running Init() (panel ReadID
832		 * mismatch is normal for some QSPI panels), make sure the panel is
833		 * actually programmed BEFORE lcddev_register / fb_register triggers
834		 * setpower() -> DisplayOn (REG 0x29). Otherwise the very first WriteReg
835		 * runs against an uninitialised LCDC controller and returns HAL_BUSY.
836		 */
837		if (p_drv_ops && p_drv_ops->p_ops && p_drv_ops->p_ops->Init)
838		{
839			p_drv_ops->p_ops->Init(&s_drv_lcd.hlcdc);
840		}
841	
842		s_drv_lcd.p_drv_ops = p_drv_ops; 
843		sem_post(&s_drv_lcd.init_sem);
844	
845		if (!p_drv_ops)
846		{
847			syslog(LOG_ERR, "ERROR: No LCD driver found, skip device register\n");
848			return -ENODEV;
849		}
850	
851	
852	#ifdef CONFIG_LCD_DEV
853	    lcd_registered = false;
854	#endif
855	    /* Retry registration to tolerate early-boot timing races. */
856	    for (retry = 0; retry < 30; retry++)
857	    {
858	#ifdef CONFIG_LCD_DEV
859	      if (!lcd_registered)
860	      {
861	        ret = lcddev_register(0);
862	        if (ret == OK || ret == -EEXIST)
863	        {
864	          lcd_registered = true;
865	          lcdinfo("lcddev_register done.");
866	        }
867	        else if (ret != -ENOENT && ret != -ENODEV)
868	        {
869	          syslog(LOG_ERR, "ERROR: lcddev_register() failed: %d\n", ret);
870	          lcd_registered = true; /* stop retrying on hard errors */
871	        }
872	      }
873	#endif
874	
875	#ifdef CONFIG_LCD_DEV
876	      if (lcd_registered)
877	      {
878	        break;
879	      }
880	#endif
881	
882	      usleep(100 * 1000);
883	    }
884	
885	    hw_pid = task_create("lcd_hw",
886	                         SCHED_PRIORITY_DEFAULT,
887	                         8192,
888	                         lcd_hw_setup_thread_entry,
889	                         NULL);
890	
891	    if (hw_pid < 0)
892	    {
893	      syslog(LOG_ERR, "ERROR: lcd_hw task_create failed: %d\n", errno);
894	    }
895	
896		return 0;
897	}
