241	static void sf32lb_lcd_wrram(FAR struct sf32lb_lcd_dev_s *dev, FAR const uint8_t *buffer,
242	                          uint16_t x0, uint16_t y0,
243	                          uint16_t x1, uint16_t y1)
244	{
245	   if (dev && dev->p_drv_ops && dev->p_drv_ops->p_ops 
246	   		  && dev->p_drv_ops->p_ops->WriteMultiplePixels)
247	   {
248	       uint16_t new_x0, new_x1, new_y0, new_y1;
249	  size_t pixels;
250	  size_t xfer_bytes;
251	
252	       DEBUGASSERT((x0 <= x1) && (y0 <= y1));
253	
254	       //disable_low_power(&drv_lcd);
255	
256	       lcd_debug_print("sf32lb_lcd_wrram [%d,%d,%d,%d]", x0, y0, x1, y1);
257	       new_x0 = x0;
258	       new_x1 = x1;
259	       new_y0 = y0;
260	       new_y1 = y1;
261	
262	
263	       DEBUGASSERT((new_x0 <= new_x1) && (new_y0 <= new_y1));
264	       DEBUGASSERT((new_x1 - new_x0 + 1) <= dev->p_drv_ops->lcd_horizonal_res);
265	       DEBUGASSERT((new_y1 - new_y0 + 1) <= dev->p_drv_ops->lcd_vertical_res);
266	
267	        /* Ensure DMA reads the latest pixel data from memory. */
268	
269	        pixels = (size_t)(new_x1 - new_x0 + 1) * (size_t)(new_y1 - new_y0 + 1);
270	        xfer_bytes = pixels * ((size_t)dev->bpp >> 3);
271	        if (buffer != NULL && xfer_bytes > 0)
272	        {
273	          up_clean_dcache((uintptr_t)buffer, (uintptr_t)buffer + xfer_bytes);
274	        }
275	       
276	        /* Drain stale completion tokens before starting a new transfer. */
277	        while (sem_trywait(&(dev->draw_sem)) == 0)
278	        {
279	        }
280	
281	        dev->hlcdc.XferCpltCallback = SendLayerDataCpltCbk;
282	        dev->hlcdc.XferErrorCallback = SendLayerDataErrCbk;
283	        dev->hlcdc.debug_cnt0++;
284	
285	
286	        dev->p_drv_ops->p_ops->WriteMultiplePixels(&dev->hlcdc, buffer, new_x0, new_y0, new_x1, new_y1);
287	        //enable_low_power(&drv_lcd);
288	        /* --------- Wait send complete (bounded wait) -----------------*/
289	        {
290	          struct timespec ts;
291	          clock_gettime(CLOCK_REALTIME, &ts);
292	          ts.tv_nsec += 200 * 1000 * 1000; /* 200ms */
293	          if (ts.tv_nsec >= 1000000000L)
294	          {
295	            ts.tv_sec += 1;
296	            ts.tv_nsec -= 1000000000L;
297	          }
298	
299	          if (sem_timedwait(&(dev->draw_sem), &ts) < 0)
300	          {
301	            lcdwarn("lcd xfer wait timeout: %d", errno);
302	          }
303	        }
304	
305	   }
306	}
