param(
    [int]$Seconds = 280,
    [string]$Out = "D:\openvela_setup\out\boot_fac_verified.txt"
)

$sp = New-Object System.IO.Ports.SerialPort "COM8", 1000000, "None", 8, "One"
$sp.ReadTimeout = 500
$sp.WriteTimeout = 2000
$sp.DtrEnable = $true
$sp.RtsEnable = $false

try { $sp.Open() } catch { Write-Output "OPEN-FAILED: $($_.Exception.Message)"; exit 1 }
Write-Output "OPENED COM8 @ 1000000 -- draining $Seconds s (do not disturb)"

$sb = New-Object System.Text.StringBuilder
$deadline = (Get-Date).AddSeconds($Seconds)
$lastReport = 0

while ((Get-Date) -lt $deadline) {
    try {
        $ch = $sp.ReadExisting()
        if ($ch.Length -gt 0) { [void]$sb.Append($ch) }
    } catch { }
    $elapsed = [int]((Get-Date) - $deadline.AddSeconds(-$Seconds)).TotalSeconds
    if ($elapsed -ge $lastReport + 30) {
        $lastReport = $elapsed
        Write-Output ("  ... {0,3}s  captured {1} chars" -f $elapsed, $sb.Length)
    }
    Start-Sleep -Milliseconds 50
}

$sp.Close()

$text = $sb.ToString()
$text = [regex]::Replace($text, "`e\[[0-9;]*[A-Za-z]", "")
Set-Content -Path $Out -Value $text -Encoding UTF8
Write-Output "SAVED: $Out  ($($text.Length) chars)"

