425	/**
426	  * @brief  Writes  to the selected LCD register.
427	  * @param  LCD_Reg: address of the selected register.
428	  * @retval None
429	  */
430	static void LCD_WriteReg(LCDC_HandleTypeDef *hlcdc, uint16_t LCD_Reg, uint8_t *Parameters, uint32_t NbParameters)
431	{
432	    uint32_t cmd;
433	    HAL_StatusTypeDef status;
434	
435	    if ((REG_WRITE_RAM == LCD_Reg) || (REG_CONTINUE_WRITE_RAM == LCD_Reg))
436	    {
437	        cmd = (0x32 << 24) | (LCD_Reg << 8);
438	    }
439	    else
440	    {
441	        cmd = (0x02 << 24) | (LCD_Reg << 8);
442	    }
443	
444	    status = HAL_LCDC_WriteU32Reg(hlcdc, cmd, Parameters, NbParameters);
445	
446	    if (status != HAL_OK)
447	    {
448	        lcdwarn("[co5300] WriteReg failed reg=0x%02x len=%lu st=%d",
449	                LCD_Reg, (unsigned long)NbParameters, status);
450	    }
451	
452	}
