input.content:
$sp = New-Object System.IO.Ports.SerialPort "COM8", 1000000, "None", 8, "One"
$sp.ReadTimeout = 200
$sp.WriteTimeout = 2000
$sp.DtrEnable = $false
$sp.RtsEnable = $false

try { $sp.Open() } catch { Write-Output "OPEN-FAILED: $($_.Exception.Message)"; exit 1 }

function Snap([int]$ms) {
    $s = ""
    $deadline = (Get-Date).AddMilliseconds($ms)
    while ((Get-Date) -lt $deadline) {
        try { $ch = $sp.ReadExisting(); if ($ch.Length -gt 0) { $s += $ch } } catch { }
        Start-Sleep -Milliseconds 40
    }
    return $s
}

function TrySeq([string]$name, [scriptblock]$body, [int]$listenMs) {
    # flush anything pending first
    [void](Snap 400)
    Write-Output "=== TRY: $name ==="
    & $body
    $out = Snap $listenMs
    $clean = [regex]::Replace($out, "`e\[[0-9;]*[A-Za-z]", "")
    if ($clean.Trim().Length -eq 0) {
        Write-Output "  (silence - no reset)"
    } else {
        $head = $clean.Substring(0, [Math]::Min(400, $clean.Length))
        Write-Output "  OUTPUT: $head"
        if ($clean -match "SFBL|NuttShell|nsh>|bootloader|FCES|ATSF32") {
            Write-Output "  *** RESET DETECTED ***"
        }
    }
}

# 1. ESP-style: assert reset via DTR, toggle, release
TrySeq "ESP-style DTR/RTS" {
    $sp.DtrEnable = $false; $sp.RtsEnable = $true;  Start-Sleep -Milliseconds 300
    $sp.DtrEnable = $true;  $sp.RtsEnable = $false; Start-Sleep -Milliseconds 300
    $sp.DtrEnable = $false; $sp.RtsEnable = $false
} 8000

# 2. DTR pulse low->high
TrySeq "DTR pulse" {
    $sp.DtrEnable = $true;  Start-Sleep -Milliseconds 400
    $sp.DtrEnable = $false; Start-Sleep -Milliseconds 400
    $sp.DtrEnable = $true
} 8000

# 3. RTS pulse
TrySeq "RTS pulse" {
    $sp.RtsEnable = $true;  Start-Sleep -Milliseconds 400
    $sp.RtsEnable = $false; Start-Sleep -Milliseconds 400
    $sp.RtsEnable = $true
} 8000

# 4. both toggled together
TrySeq "both pulse" {
    $sp.DtrEnable = $false; $sp.RtsEnable = $false; Start-Sleep -Milliseconds 400
    $sp.DtrEnable = $true;  $sp.RtsEnable = $true;  Start-Sleep -Milliseconds 400
    $sp.DtrEnable = $false; $sp.RtsEnable = $false
} 8000

$sp.Close()
Write-Output "done"

