     ```c
     static int lcdfb_updateearea(FAR struct fb_vtable_s *vtable,
                                  FAR const struct fb_area_s *area)
     {
       FAR struct lcdfb_dev_s *priv = (FAR struct lcdfb_dev_s *)vtable;
       FAR struct lcd_planeinfo_s *pinfo = &priv->pinfo;
       FAR uint8_t *run = priv->fbmem;
       fb_coord_t startx = 0, endx = priv->xres - 1, width = priv->xres;
       fb_coord_t starty = 0, endy = priv->yres - 1;
       int ret;

       if (area != NULL)
         {
           startx = area->x;              if (startx < 0) startx = 0;
           endx = startx + area->w - 1;   if (endx >= priv->xres) endx = priv->xres - 1;
           starty = area->y;              if (starty < 0) starty = 0;
           endy = starty + area->h - 1;   if (endy >= priv->yres) endy = priv->yres - 1;
           if (pinfo->bpp < 8) { unsigned int pixperbyte = 8 / pinfo->bpp; startx &= ~(pixperbyte - 1); }
           run  = priv->fbmem + starty * priv->stride;
           run += (startx * pinfo->bpp + 7) >> 3;
         }

       if (pinfo->putarea != NULL)
         {
           ret = pinfo->putarea(pinfo->dev, starty, endy, startx, endx, run, priv->stride);
           if (ret < 0) { lcderr("Failed to update area"); return ret; }
         }
       else
         {
           width = endx - startx + 1;
           for (row = starty; row <= endy; row++)
             {
               ret = pinfo->putrun(pinfo->dev, row, startx, run, width);
               if (ret < 0) { lcderr("Failed to update row"); return ret; }
               run += priv->stride;
             }
         }
       if (pinfo->redraw != NULL) { pinfo->redraw(pinfo->dev); }
       return OK;
     }
