   - **`D:\openvela_setup\out\putarea2.txt`** — the full `sf32lb_lcd_putarea` from `vendor/sifli/boards/sf32lb52/drivers/lcd/sf32lb_lcd.c` (read-only, protected by 零改动). **THE KEY TWO-PATH STRUCTURE:**
     ```c
     static int sf32lb_lcd_putarea(FAR struct lcd_dev_s *dev,
                               fb_coord_t row_start, fb_coord_t row_end,
                               fb_coord_t col_start, fb_coord_t col_end,
                               FAR const uint8_t *buffer, fb_coord_t stride)
     {
       FAR struct sf32lb_lcd_dev_s *priv = (FAR struct sf32lb_lcd_dev_s *)dev;
       size_t bytes_per_pixel;
       size_t row_bytes;

       if (s_fb_registering || !s_lcd_hw_ready) { return OK; }

       bytes_per_pixel = priv->bpp >> 3;
       row_bytes = (size_t)(col_end - col_start + 1) * bytes_per_pixel;

       lcd_debug_print("row_start: %d row_end: %d col_start: %d col_end: %d\n",
              row_start, row_end, col_start, col_end);
       DEBUGASSERT(buffer && ((uintptr_t)buffer & 1) == 0);

       if (priv->bpp == 8)
         {
           /* ... converts 8bpp -> RGB565 ... then, PER ROW (y0 == y1): */
           sf32lb_lcd_setarea(priv, col_start, y, col_end, y);
           sf32lb_lcd_wrram(priv, (FAR const uint8_t *)conv, col_start, y, col_end, y);
         }

       if ((size_t)stride == row_bytes)          /* <-- FULL-WIDTH FAST PATH (works) */
         {
           fb_coord_t y = row_start;
           const fb_coord_t chunk_rows = 24;
           while (y <= row_end)
             {
               fb_coord_t y1 = y + chunk_rows - 1;
               FAR const uint8_t *src;
               if (y1 > row_end) { y1 = row_end; }
               src = buffer + (y - row_start) * stride;
               sf32lb_lcd_setarea(priv, col_start, y, col_end, y1);
               sf32lb_lcd_wrram(priv, src, col_start, y, col_end, y1);
               y = y1 + 1;
             }
         }
       else                                      /* <-- PARTIAL-WIDTH PATH (fails) */
         {
           fb_coord_t y;
           /* The source rows are not tightly packed for this area, so send
            * one row at a time using stride to step through the source buffer. */
           for (y = row_start; y <= row_end; y++)
             {
               FAR const uint8_t *src = buffer + (y - row_start) * stride;
               sf32lb_lcd_setarea(priv, col_start, y, col_end, y);   /* y0 == y1, SINGLE ROW */
               sf32lb_lcd_wrram(priv, src, col_start, y, col_end, y);
             }
         }
       sf32lb_lcd_ensure_display_on(priv);
       return OK;
     }
     ```
     Also captured: `sf32lb_lcd_setarea` (calls `p_ops->SetRegion(&dev->hlcdc, new_x0, new_y0, new_x1, new_y1)`), `sf32lb_lcd_wrram` (does `up_clean_dcache(buffer, buffer + xfer_bytes)` where `xfer_bytes = pixels * (bpp>>3)`, drains `draw_sem` via `sem_trywait`, sets `XferCpltCallback = SendLayerDataCpltCbk`, calls `p_ops->WriteMultiplePixels(&dev->hlcdc, buffer, new_x0, new_y0, new_x1, new_y1)`, then `sem_timedwait` with a **200 ms** timeout and `lcdwarn("lcd xfer wait timeout: %d", errno)` on failure), and `sf32lb_lcd_ensure_display_on` (calls `p_ops->DisplayOn` when `dev->power <= 0`).

   - **`D:\openvela_setup\out\co5300_dump.c`** (608 lines, local, pre-existing). Grepped this session for:
     - `COL_OFFSET (0)` / `ROW_OFFSET (0)` for 390×450 (lines 26-28)
