1071: static HAL_StatusTypeDef WaitBusy(LCDC_HandleTypeDef *lcdc)
1072: {
1073:     const uint32_t timeout_ms = LCDC_TIMEOUT_SECONDS * 1000;
1074: 
1075:     uint32_t start_tick = HAL_GetTick();
1076: 
1077:     if (HAL_LCDC_IS_DPI_IF(lcdc->Init.lcd_itf))   return HAL_OK;
1078: #ifdef HAL_DSI_MODULE_ENABLED
1079:     if (HAL_DSI_IS_VIDEO_MODE(&lcdc->hdsi) && HAL_LCDC_IS_DSI_VID_IF(lcdc->Init.lcd_itf)) return HAL_OK;
1080: #endif /* HAL_DSI_MODULE_ENABLED */
1081: 
1082:     do
1083:     {
1084:         if ((lcdc->Instance->STATUS & LCD_IF_STATUS_LCD_BUSY) || (lcdc->Instance->LCD_SINGLE & LCD_IF_LCD_SINGLE_LCD_BUSY)) continue;
1085: 
1086: #ifdef HAL_DSI_MODULE_ENABLED
1087:         if (HAL_LCDC_IS_DSI_IF(lcdc->Init.lcd_itf))
1088:         {
1089: #ifndef HAL_USING_HTOL
1090:             if (HAL_DSI_IsBusy(&lcdc->hdsi)) continue;
1091: #endif /* HAL_USING_HTOL */
1092:         }
1093: #endif /* HAL_DSI_MODULE_ENABLED */
1094: 
1095:         return HAL_OK;
1096:     }
1097:     while (HAL_GetTick() - start_tick < timeout_ms);
1098: 
1099:     lcdc->ErrorCode |= HAL_LCDC_ERROR_TIMEOUT;
1100:     LCDC_LOG_E("WaitBusy Timeout");
1101:     //HAL_LCDC_ASSERT(0);
1102: 
1103:     return HAL_TIMEOUT;
1104: }

