1008: static HAL_StatusTypeDef SendSingleCmd(LCDC_HandleTypeDef *lcdc, uint32_t addr, uint32_t addr_len)
1009: {
1010:     if (0 == addr_len) return HAL_OK;
1011: 
1012:     HAL_LCDC_ASSERT((addr_len > 0) && (addr_len <= 4));
1013: 
1014:     if (HAL_LCDC_IS_SPI_IF(lcdc->Init.lcd_itf))
1015:     {
1016:         uint32_t config;
1017:         uint32_t byte_gap = lcdc->Init.cfg.spi.bytes_gap_us;
1018: 
1019:         WaitBusy(lcdc);
1020:         config = lcdc->Instance->SPI_IF_CONF;
1021:         config &= ~(LCD_IF_SPI_IF_CONF_RD_LEN_Msk | LCD_IF_SPI_IF_CONF_SPI_RD_MODE_Msk | LCD_IF_SPI_IF_CONF_WR_LEN_Msk);
1022: 
1023:         if (byte_gap > 0)
1024:         {
1025:             config |= MAKE_REG_VAL(0, LCD_IF_SPI_IF_CONF_SPI_RD_MODE_Msk, LCD_IF_SPI_IF_CONF_SPI_RD_MODE_Pos)
1026:                       | MAKE_REG_VAL(0, LCD_IF_SPI_IF_CONF_WR_LEN_Msk, LCD_IF_SPI_IF_CONF_WR_LEN_Pos);
1027: 
1028:             while (addr_len > 0)
1029:             {
1030:                 WAIT_LCDC_SINGLE_BUSY(lcdc);
1031:                 lcdc->Instance->LCD_WR = (addr >> ((addr_len - 1) << 3)) & 0xFF;
1032:                 lcdc->Instance->LCD_SINGLE = LCD_IF_LCD_SINGLE_WR_TRIG;
1033: 
1034:                 if (byte_gap > 1) HAL_Delay_us(byte_gap);
1035: 
1036:                 addr_len--;
1037:             }
1038:         }
1039:         else
1040:         {
1041:             config |= MAKE_REG_VAL(0, LCD_IF_SPI_IF_CONF_SPI_RD_MODE_Msk, LCD_IF_SPI_IF_CONF_SPI_RD_MODE_Pos)
1042:                       | MAKE_REG_VAL((addr_len - 1), LCD_IF_SPI_IF_CONF_WR_LEN_Msk, LCD_IF_SPI_IF_CONF_WR_LEN_Pos);
1043: 
1044: 
1045:             lcdc->Instance->SPI_IF_CONF = config;
1046:             lcdc->Instance->LCD_WR = (addr);
1047:             lcdc->Instance->LCD_SINGLE = LCD_IF_LCD_SINGLE_WR_TRIG;
1048:         }
1049:     }
1050:     else if (HAL_LCDC_IS_DBI_IF(lcdc->Init.lcd_itf) || HAL_LCDC_IS_DSI_IF(lcdc->Init.lcd_itf))
1051:     {
1052:         do
1053:         {
1054:             WaitBusy(lcdc);
1055:             lcdc->Instance->LCD_WR = (addr >> ((addr_len - 1) << 3)) & 0xFF;
1056:             lcdc->Instance->LCD_SINGLE = LCD_IF_LCD_SINGLE_WR_TRIG;
1057: 
1058:             addr_len--;
1059:         }
1060:         while (addr_len > 0);
1061:     }
1062: 
1063: 
1064:     return HAL_OK;
1065: 
1066: }

