  [int]$WaitUnplugSec = 180,
  [int]$WaitReplugSec = 120
)

$log = "D:\openvela_setup\out\flash_watch.log"
Remove-Item $log -ErrorAction SilentlyContinue
function W($m) { $m | Tee-Object -FilePath $log -Append }

if (-not (Test-Path $Image)) { W ("IMAGE NOT FOUND: " + $Image); exit 1 }
