if ($rc -ne 0) { W "FAILED"; exit 1 }
W "SUCCESS"

if ($CaptureSecs -gt 0) {
  W "watcher: grabbing the serial port NOW to catch the boot log"
  $sp = New-Object System.IO.Ports.SerialPort "COM8",1000000,"None",8,"One"
  $sp.DtrEnable = $false
  $sp.RtsEnable = $false
  $sp.ReadTimeout = 500
  try {
    $sp.Open()
    W ("watcher: port open at " + (Get-Date -Format 'HH:mm:ss.fff'))
    $sb = New-Object System.Text.StringBuilder
    $t2 = Get-Date
    while (((Get-Date) - $t2).TotalSeconds -lt $CaptureSecs) {
      try { $s = $sp.ReadExisting(); if ($s) { [void]$sb.Append($s) } } catch {}
      Start-Sleep -Milliseconds 100
    }
    $sp.Close()
    W "--- BOOT LOG ---"
    W $sb.ToString()
    W "--- END BOOT LOG ---"
  } catch {
    W ("capture failed: " + $_.ToString())
  }
}

