param([int]$CaptureSecs = 30)

$log = "D:\openvela_setup\out\i2cprobe.log"
Remove-Item $log -ErrorAction SilentlyContinue
function W($m) { $m | Tee-Object -FilePath $log -Append }

$sp = New-Object System.IO.Ports.SerialPort "COM8",1000000,"None",8,"One"
$sp.DtrEnable = $false
$sp.RtsEnable = $false
$sp.ReadTimeout = 500
$sb = New-Object System.Text.StringBuilder

function Drain($secs) {
  $t = Get-Date
  while (((Get-Date) - $t).TotalSeconds -lt $secs) {
    try { $s = $sp.ReadExisting(); if ($s) { [void]$script:sb.Append($s) } } catch {}
    Start-Sleep -Milliseconds 100
  }
}

try {
  $sp.Open()
  W "port open"
  Drain 3

  $cmds = @("", "i2c", "i2c dev -b 0 0x38", "i2c dev -b 1 0x6a", "i2c dev -b 0 0x70", "i2c get -b 0 0x38 0xa0")
  foreach ($c in $cmds) {
    W ("--- SEND: [" + $c + "]")
    $sp.Write($c + "`n")
    Drain 6
  }

  Drain $CaptureSecs
  $sp.Close()
} catch {
  W ("serial failed: " + $_.ToString())
}

W "--- SERIAL LOG ---"
W $sb.ToString()
W "--- END ---"

