$ErrorActionPreference = "Stop"

$src = "C:\Users\" + [char]0x5F20 + [char]0x5B50 + [char]0x7409 + "\.claude\projects\C--Users----\8187a9cf-9a59-4fc5-b7db-7cce22ed0630.jsonl"
$dst = "D:\openvela_setup\out\session_redacted.jsonl"
$log = "D:\openvela_setup\out\redact_report.txt"

function W($m) { $m | Tee-Object -FilePath $log -Append }
Remove-Item $log -ErrorAction SilentlyContinue

if (-not (Test-Path $src)) { W "SRC NOT FOUND: $src"; exit 1 }
W ("src: " + $src)
W ("src size: " + (Get-Item $src).Length)

$text = [System.IO.File]::ReadAllText($src, [System.Text.Encoding]::UTF8)
W ("chars read: " + $text.Length)

$total = 0

# 1) GitHub PAT - full form, then the bare body alone (never printed anywhere)
$m = [regex]::Match($text, 'ghp_[A-Za-z0-9]{36}')
if ($m.Success) {
  $full = $m.Value
  $body = $full.Substring(4)
  # count first, then replace
  $nFull = ([regex]::Matches($text, [regex]::Escape($full))).Count
  $text = $text.Replace($full, 'ghp_***REDACTED***')
  W ("PAT full form  : " + $nFull + " occurrence(s) -> ghp_***REDACTED***")
  $total += $nFull

  # bare body: replace remaining standalone occurrences
  $nBody = ([regex]::Matches($text, [regex]::Escape($body))).Count
  if ($nBody -gt 0) {
    $text = $text.Replace($body, '***REDACTED***')
    W ("PAT bare body  : " + $nBody + " occurrence(s) -> ***REDACTED***")
    $total += $nBody
  } else {
    W "PAT bare body  : 0 occurrences (all were inside the full form)"
  }
} else {
  W "PAT            : no ghp_<36> match found"
}

# 2) other secret shapes
foreach ($p in @(
    @{ re = 'sk-[A-Za-z0-9_-]{20,}';          rep = 'sk-***REDACTED***' },
    @{ re = 'Bearer\s+[A-Za-z0-9._\-+/=]+';   rep = 'Bearer ***REDACTED***' },
    @{ re = '***REDACTED***';                    rep = '***REDACTED***' }
  )) {
  $n = ([regex]::Matches($text, $p.re)).Count
  if ($n -gt 0) {
    $text = [regex]::Replace($text, $p.re, $p.rep)
    W ("pattern " + $p.re + " : " + $n + " occurrence(s)")
    $total += $n
  }
}

W ("total redactions: " + $total)

# write UTF-8 with NO BOM so the jsonl parser stays happy
$enc = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($dst, $text, $enc)
W ("dst: " + $dst)
W ("dst size: " + (Get-Item $dst).Length)

# self-check: scan the OUTPUT for anything that still looks like a credential
$out = [System.IO.File]::ReadAllText($dst, [System.Text.Encoding]::UTF8)
$leftover = 0
foreach ($p in @('ghp_[A-Za-z0-9]{36}', 'sk-[A-Za-z0-9_-]{20,}', '***REDACTED***')) {
  $n = ([regex]::Matches($out, $p)).Count
  W ("  leftover check [" + $p + "] = " + $n)
  $leftover += $n
}
if ($leftover -eq 0) { W "SELFCHECK: CLEAN" } else { W "SELFCHECK: *** STILL DIRTY ***" }

# sanity: every line must still be valid JSON-ish (starts with { ends with })
$lines = [System.IO.File]::ReadAllLines($dst, [System.Text.Encoding]::UTF8)
$bad = 0
foreach ($l in $lines) {
  if ($l.Trim().Length -eq 0) { continue }
  if (-not ($l.TrimStart().StartsWith("{") -and $l.TrimEnd().EndsWith("}"))) { $bad++ }
}
W ("lines: " + $lines.Count + "   malformed: " + $bad)

